SELECT 100.0 * SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM Player p
JOIN (
  SELECT player_api_id, preferred_foot
  FROM Player_Attributes
  WHERE id IN (
    SELECT MAX(id) FROM Player_Attributes GROUP BY player_api_id
  )
) pa ON pa.player_api_id = p.player_api_id
WHERE substr(p.birthday,1,4) BETWEEN '1987' AND '1992';

answer_sql:
